# Pulumi ComponentResource: Application Infrastructure Wrapper

Below is a production-ready implementation of a Pulumi ComponentResource that wraps S3, RDS, and IAM resources with environment-aware configuration.

## Component Resource Definition

```typescript
// lib/applicationResources.ts
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface ApplicationResourcesArgs {
  environment: "dev" | "prod";
  bucketName?: string;
  dbInstanceClass?: string;
  multiAz?: boolean;
  backupRetentionDays?: number;
  vpcCidr?: string;
}

export class ApplicationResources extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.Bucket;
  public readonly bucketVersioning: aws.s3.BucketVersioningV2;
  public readonly bucketEncryption: aws.s3.BucketServerSideEncryptionConfigurationV2;
  public readonly bucketPublicAccessBlock: aws.s3.BucketPublicAccessBlock;

  public readonly dbInstance: aws.rds.Instance;
  public readonly dbSecurityGroup: aws.ec2.SecurityGroup;

  public readonly serviceRole: aws.iam.Role;
  public readonly serviceRolePolicy: aws.iam.RolePolicy;
  public readonly serviceInstanceProfile: aws.iam.InstanceProfile;

  constructor(
    name: string,
    args: ApplicationResourcesArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("custom:aws:ApplicationResources", name, {}, opts);

    const config = new pulumi.Config();
    const awsConfig = new pulumi.Config("aws");
    const region = awsConfig.require("region");
    const caller = aws.getCallerIdentityOutput();
    const defaultParent = { parent: this };

    // ============ S3 BUCKET ============
    const bucketName =
      args.bucketName || `app-assets-${args.environment}-${pulumi.getStack()}-${Date.now()}`;

    this.bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        bucket: bucketName,
        forceDestroy: args.environment === "dev", // Allow destruction in dev
      },
      defaultParent
    );

    // Enable Versioning (required by spec)
    this.bucketVersioning = new aws.s3.BucketVersioningV2(
      `${name}-versioning`,
      {
        bucket: this.bucket.id,
        versioningConfiguration: {
          status: "Enabled",
        },
      },
      defaultParent
    );

    // Enable Server-Side Encryption (AES-256, required by spec)
    this.bucketEncryption = new aws.s3.BucketServerSideEncryptionConfigurationV2(
      `${name}-encryption`,
      {
        bucket: this.bucket.id,
        rules: [
          {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: "AES256",
            },
          },
        ],
      },
      defaultParent
    );

    // Block all public access (required by spec)
    this.bucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock(
      `${name}-pab`,
      {
        bucket: this.bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      defaultParent
    );

    // ============ RDS POSTGRESQL ============
    const dbUsername = "postgres";
    const dbPassword = config.requireSecret("dbPassword"); // Stored encrypted in stack config
    const dbName = "application";
    const dbInstanceClass =
      args.dbInstanceClass ||
      (args.environment === "prod" ? "db.t3.medium" : "db.t3.micro");
    const multiAz =
      args.multiAz !== undefined ? args.multiAz : args.environment === "prod";
    const backupRetention =
      args.backupRetentionDays ||
      (args.environment === "prod" ? 30 : 7);
    const vpcCidr = args.vpcCidr || "10.0.0.0/8"; // VPC CIDR for security group ingress

    // RDS Security Group
    this.dbSecurityGroup = new aws.ec2.SecurityGroup(
      `${name}-db-sg`,
      {
        description: `Security group for ${name} RDS PostgreSQL instance (${args.environment})`,
        ingress: [
          {
            fromPort: 5432,
            toPort: 5432,
            protocol: "tcp",
            cidrBlocks: [vpcCidr], // Restrict to VPC
            description: "PostgreSQL from VPC",
          },
        ],
        egress: [
          {
            fromPort: 0,
            toPort: 0,
            protocol: "-1",
            cidrBlocks: ["0.0.0.0/0"],
            description: "Allow all outbound",
          },
        ],
      },
      defaultParent
    );

    // RDS Instance (deletion protection required by spec)
    this.dbInstance = new aws.rds.Instance(
      `${name}-db`,
      {
        identifier: `${name}-db-${args.environment}`,
        engine: "postgres",
        engineVersion: "15",
        instanceClass: dbInstanceClass,
        allocatedStorage: 20,
        storageType: "gp3",
        dbName: dbName,
        username: dbUsername,
        password: dbPassword,
        skipFinalSnapshot: args.environment === "dev",
        finalSnapshotIdentifier:
          args.environment === "prod"
            ? `${name}-final-snapshot-${Date.now()}`
            : undefined,
        deletionProtection: args.environment === "prod", // Required by spec
        multiAz: multiAz, // Multi-AZ for prod
        backupRetentionPeriod: backupRetention, // >= 7 days required by spec
        backupWindow: "03:00-04:00",
        maintenanceWindow: "mon:04:00-mon:05:00",
        storageEncrypted: true, // Encrypt at rest
        publiclyAccessible: false, // Never publicly accessible (required by spec)
        vpcSecurityGroupIds: [this.dbSecurityGroup.id],
        autoMinorVersionUpgrade: true,
      },
      defaultParent
    );

    // ============ IAM ROLE FOR SERVICE ACCOUNT ============
    // Assume role policy for EC2 instances
    const assumeRolePolicyDoc = aws.iam
      .getPolicyDocumentOutput({
        statements: [
          {
            actions: ["sts:AssumeRole"],
            principals: {
              type: "Service",
              identifiers: ["ec2.amazonaws.com"],
            },
          },
        ],
      })
      .apply((doc) => doc.json);

    this.serviceRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        name: `${name}-service-role-${args.environment}`,
        assumeRolePolicy: assumeRolePolicyDoc,
      },
      defaultParent
    );

    // Instance profile for EC2
    this.serviceInstanceProfile = new aws.iam.InstanceProfile(
      `${name}-instance-profile`,
      {
        role: this.serviceRole.name,
      },
      defaultParent
    );

    // Least-privilege policy (no wildcards in prod, required by spec)
    const servicePolicyDoc = pulumi
      .all([this.bucket.arn, this.dbInstance.endpoint, caller.accountId])
      .apply(([bucketArn, dbEndpoint, accountId]) => {
        const statements: any[] = [
          {
            sid: "S3BucketReadWrite",
            actions: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
            resources: [`${bucketArn}/*`],
          },
          {
            sid: "S3BucketList",
            actions: ["s3:ListBucket"],
            resources: [bucketArn],
          },
        ];

        // Restrict Secrets Manager access in prod (least privilege)
        if (args.environment === "prod") {
          statements.push({
            sid: "SecretsManagerReadOnly",
            actions: ["secretsmanager:GetSecretValue"],
            resources: [
              `arn:aws:secretsmanager:${region}:${accountId}:secret:${name}/*`,
            ],
          });
        } else {
          // Dev can be more permissive but still scoped
          statements.push({
            sid: "SecretsManagerDev",
            actions: ["secretsmanager:GetSecretValue"],
            resources: [
              `arn:aws:secretsmanager:${region}:${accountId}:secret:*`,
            ],
          });
        }

        return JSON.stringify({ Version: "2012-10-17", Statement: statements });
      });

    this.serviceRolePolicy = new aws.iam.RolePolicy(
      `${name}-service-policy`,
      {
        role: this.serviceRole.id,
        policy: servicePolicyDoc,
      },
      defaultParent
    );

    // Register outputs
    this.registerOutputs({
      bucketName: this.bucket.id,
      bucketArn: this.bucket.arn,
      dbEndpoint: this.dbInstance.endpoint,
      dbPort: this.dbInstance.port,
      dbName: this.dbInstance.dbName,
      dbUsername: this.dbInstance.username,
      roleArn: this.serviceRole.arn,
      roleName: this.serviceRole.name,
      instanceProfileArn: this.serviceInstanceProfile.arn,
    });
  }
}
```

## Main Stack File

```typescript
// index.ts
import * as pulumi from "@pulumi/pulumi";
import { ApplicationResources } from "./lib/applicationResources";

const config = new pulumi.Config();
const environment = config.require("environment") as "dev" | "prod";

const app = new ApplicationResources("app", {
  environment: environment,
  dbInstanceClass: config.get("dbInstanceClass"),
  multiAz: config.getBoolean("multiAz"),
  backupRetentionDays: config.getNumber("backupRetentionDays"),
  vpcCidr: config.get("vpcCidr") || "10.0.0.0/8",
});

// Export key values
export const bucketName = app.bucket.id;
export const bucketArn = app.bucket.arn;
export const dbEndpoint = app.dbInstance.endpoint;
export const dbPort = app.dbInstance.port;
export const dbName = app.dbInstance.dbName;
export const serviceRoleArn = app.serviceRole.arn;
export const instanceProfileArn = app.serviceInstanceProfile.arn;
```

## Stack Configuration Files

```yaml
# Pulumi.dev.yaml
config:
  aws:region: us-east-1
  environment: dev
  dbInstanceClass: db.t3.micro
  multiAz: false
  backupRetentionDays: 7
  vpcCidr: 10.0.0.0/8
  dbPassword:
    secure: AAABAxxxxxxxxxxxxxx  # Encrypted via `pulumi config set --secret`
```

```yaml
# Pulumi.prod.yaml
config:
  aws:region: us-east-1
  environment: prod
  dbInstanceClass: db.t3.medium
  multiAz: true
  backupRetentionDays: 30
  vpcCidr: 10.0.0.0/8
  dbPassword:
    secure: AAABAyyyyyyyyyyyyyy  # Encrypted via `pulumi config set --secret`
```

## Deployment Commands

```bash
# Set encrypted secrets (one-time per stack)
pulumi config set --secret dbPassword <password> --stack dev
pulumi config set --secret dbPassword <password> --stack prod

# Deploy to dev
pulumi up --stack dev

# Deploy to prod
pulumi up --stack prod
```

## Key Features

| Requirement | Implementation |
|---|---|
| **S3 Versioning** | `BucketVersioningV2` with status `Enabled` |
| **S3 Encryption** | `BucketServerSideEncryptionConfigurationV2` with AES256 |
| **S3 Public Access** | `BucketPublicAccessBlock` blocks all public access |
| **RDS Deletion Protection** | Enabled for prod only |
| **RDS Backup Retention** | 7 days (dev), 30 days (prod) |
| **RDS Multi-AZ** | Prod only; dev single-AZ |
| **RDS Security** | Not publicly accessible; security group restricted to VPC CIDR |
| **IAM Least Privilege** | Scoped S3 actions, environment-specific Secrets Manager access |
| **Secrets Management** | Encrypted via Pulumi stack config (`--secret` flag) |
| **Environment Isolation** | Separate `dev.yaml`/`prod.yaml` stacks; independent deployment |

The ComponentResource provides a reusable, type-safe abstraction that enforces compliance with all acceptance criteria while supporting dev/prod environment configuration idiomatically via Pulumi stack configs.
